/**
 * Confidence calibration for the demo detector: an isotonic map fitted on the validation
 * split only, applied to the raw network score so that a stated confidence means what it
 * says. Generated by scripts/build_demo_model.py; do not edit by hand.
 */
const KNOTS_X = [0.050107769668102264, 0.05014751851558685, 0.05427582934498787, 0.0543285496532917, 0.09513694792985916, 0.09516782313585281, 0.10838408023118973, 0.10856079310178757, 0.11743659526109695, 0.11773652583360672, 0.13355261087417603, 0.13364988565444946, 0.20075340569019318, 0.20105303823947906, 0.21050617098808289, 0.21134814620018005, 0.2465035319328308, 0.24738004803657532, 0.37233850359916687, 0.3730103671550751, 0.3806755840778351, 0.3829067647457123, 0.40040889382362366, 0.4008261263370514, 0.4188772737979889, 0.4193362891674042, 0.46793442964553833, 0.46865710616111755, 0.47626978158950806, 0.47644278407096863, 0.5472828149795532, 0.5490854382514954, 0.6098166704177856, 0.6099197268486023, 0.6530163884162903, 0.6543511748313904, 0.6878930330276489, 0.6901077628135681, 0.7011416554450989, 0.7013828158378601, 0.7622886300086975, 0.762991726398468, 0.7751647233963013, 0.776009202003479, 0.8131520748138428, 0.8134884834289551, 0.9215216636657715, 0.9230507016181946, 0.9634497761726379];
const KNOTS_Y = [0.0, 0.09090909090909091, 0.09090909090909091, 0.12328767123287675, 0.12328767123287675, 0.15217391304347827, 0.15217391304347827, 0.15384615384615385, 0.15384615384615385, 0.17142857142857143, 0.17142857142857143, 0.211864406779661, 0.211864406779661, 0.23809523809523808, 0.23809523809523808, 0.24528301886792453, 0.24528301886792453, 0.30597014925373134, 0.30597014925373134, 0.3333333333333333, 0.3333333333333333, 0.35294117647058826, 0.35294117647058826, 0.4166666666666667, 0.4166666666666667, 0.5128205128205128, 0.5128205128205128, 0.5555555555555556, 0.5555555555555556, 0.56, 0.56, 0.6666666666666666, 0.6666666666666666, 0.7435897435897436, 0.7435897435897436, 0.76, 0.76, 0.7692307692307693, 0.7692307692307693, 0.7903225806451613, 0.7903225806451613, 0.8181818181818182, 0.8181818181818182, 0.9375, 0.9375, 0.9739130434782609, 0.9739130434782609, 1.0, 1.0];
const EPS = 1e-06;

export const CALIBRATION = {
  method: 'isotonic',
  nKnots: KNOTS_X.length,
  eceBefore: 0.08217057322192352,
  eceAfter: 0.033066382365472304,
  brierBefore: 0.16134849524828862,
  brierAfter: 0.15493932653558312,
  fitSplit: 'val',
  evalSplit: 'test',
};

export function calibrate(raw) {
  const lo = KNOTS_X[0];
  const hi = KNOTS_X[KNOTS_X.length - 1];
  const s = Math.min(Math.max(raw, lo), hi);
  let base;
  if (s <= lo) base = KNOTS_Y[0];
  else if (s >= hi) base = KNOTS_Y[KNOTS_Y.length - 1];
  else {
    let i = KNOTS_X.length - 1;
    while (i > 0 && KNOTS_X[i - 1] >= s) i--;
    const xa = KNOTS_X[i - 1], xb = KNOTS_X[i], ya = KNOTS_Y[i - 1], yb = KNOTS_Y[i];
    base = xb === xa ? yb : ya + ((yb - ya) * (s - xa)) / (xb - xa);
  }
  return base * (1 - EPS) + EPS * Math.min(Math.max(raw, 0), 1);
}

